"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3244],{49551:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"client","desc":"Client entry point. Starts replication, boots the ECS, mounts the UI, then\\npulls the initial world snapshot from the server.\\n\\nThe listeners go on before `lync.start`, which seals what a side has\\nattached; `start` then waits for the server\'s remotes to replicate, so\\neverything below it runs on a live connection.\\n\\n`startup` is handed the shared systems alone. Applying replication is the\\nonly thing the client ever did on a tick, and Lync dispatches that to the\\nlisteners below instead, so there are no client-only systems to register.","tags":["core"],"realm":["Client"],"source":{"line":18,"path":"src/main/client/client.client.luau"}}')}}]);